try{using(var t=new Transaction(document,"First T1 bottom chord - verify timber family")){t.Start();var s=new FilteredElementCollector(document).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().Single(s=>s.FamilyName=="LC Rectangular Timber"&&s.Name=="90x35 MGP10");s.Activate();document.Regenerate();var level=new FilteredElementCollector(document).OfClass(typeof(Level)).Cast<Level>().Single(l=>l.Name.StartsWith("01 First FFL"));var e=document.Create.NewFamilyInstance(Line.CreateBound(new XYZ(10170/304.8,150/304.8,5785/304.8),new XYZ(10170/304.8,5345/304.8,5785/304.8)),s,level,Autodesk.Revit.DB.Structure.StructuralType.Beam);Autodesk.Revit.DB.Structure.StructuralFramingUtils.DisallowJoinAtEnd(e,0);Autodesk.Revit.DB.Structure.StructuralFramingUtils.DisallowJoinAtEnd(e,1);e.get_Parameter(BuiltInParameter.Z_JUSTIFICATION).Set(1);e.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).Set("TEST-T1-BC");document.Regenerate();var box=e.get_BoundingBox(null);var r=new{id=e.Id.Value,min=box.Min.ToString(),max=box.Max.ToString(),parameters=e.Parameters.Cast<Parameter>().Where(p=>p.Definition.Name.Contains("Justification")||p.Definition.Name.Contains("Extension")||p.Definition.Name.Contains("Material")).Select(p=>new{name=p.Definition.Name,value=p.AsValueString()}).ToArray()};t.Commit();return r;}}catch(Exception ex){return new{failure=ex.ToString()};}
